def independent_max(builder,E1,E2,p):
    for s in (2,1,0):
        S,*_=builder(E1,E2,p,s)
        if S: return s
    return None

def core_compatible(core,i,j,env):
    # synthetic event exposes the two correlated interface P/Ms; bridge_ok remains local,
    # but env membership already enforces E1-E2 correlation.
    s1=(0,(env[1][0],),0,0,0); s2=(0,(env[1][1],),0,0,0)
    return bridge_ok(core,i,s1,0) and bridge_ok(core,j,s2,0)

def pm_bridge(pmA, pmB):
    PA,MA=pmA; PB,MB=pmB
    return ((MA==0 or (MA&PB)!=0) and (MB==0 or (MB&PA)!=0))

def compatible(core,i,j,e1,e2):
 f1=(0,(core[1][i],),0,0,0); f2=(0,(core[1][j],),0,0,0)
 return bridge_ok(f1,0,e1,0) and bridge_ok(f2,0,e2,0)

def ownmax_core(core_records,h1,h2,i,j):
 for thr in (2,1,0):
  ex=extpairs(h1,h2,thr)
  for c in core_records:
   if int(c[2])<thr: continue
   if any(compatible(c,i,j,e1,e2) for e1,e2 in ex): return thr
 return None

def outrec(core,i,j,e1,e2):
 rem=[k for k in range(5) if k not in (i,j)]
 return (core[0]|e1[0]|e2[0],tuple(core[1][k] for k in rem)+(e1[1][2],e2[1][2]),min(core[2],e1[2],e2[2]),tuple(core[3])+(e1[3],e2[3]),int(core[4] and e1[4] and e2[4]))

def ext_index(h1,h2,thr):
 ex=extpairs(h1,h2,thr); idx={}
 for e1,e2 in ex: idx.setdefault((e1[1][0],e2[1][0]),[]).append((e1,e2))
 return ex,idx

def matching_blocks(c,i,j,idx):
 a,b=c[1][i],c[1][j]
 for (x,y),vals in idx.items():
  if pmok(a,x) and pmok(b,y): yield vals

def materialize_raw(h1,h2,i,j,thr):
 ex,idx=ext_index(h1,h2,thr); out=set(); parents=0
 for tr in base:
  c=aggabc(tr)
  if int(c[2])<thr: continue
  for vals in matching_blocks(c,i,j,idx):
   for e1,e2 in vals: parents+=1; out.add(outrec(c,i,j,e1,e2))
 return frozenset(out),parents,len(ex)

def materialize_macro(h1,h2,i,j,thr):
 ex,idx=ext_index(h1,h2,thr); out=set(); parents=0
 for c in TABC:
  if int(c[2])<thr: continue
  for vals in matching_blocks(c,i,j,idx):
   for e1,e2 in vals: parents+=1; out.add(outrec(c,i,j,e1,e2))
 return frozenset(out),parents,len(ex)

def canon(edges):
    # canonical under permutation of external labels 1,2,3; core fixed
    reps=[]
    for p in itertools.permutations((1,2,3)):
        mp={0:0,1:p[0],2:p[1],3:p[2]}
        ee=tuple(sorted(tuple(sorted((mp[u],mp[v]))) for u,v in edges))
        reps.append(ee)
    return min(reps)

def ext_slot_map(edges):
    out={1:{},2:{},3:{}}
    for e in (1,2,3):
        nbs=sorted(v if u==e else u for u,v in edges if u==e or v==e)
        assert len(nbs)<=3
        for slot,nb in enumerate(nbs): out[e][nb]=slot
    return out

def ext_joint(edges,score):
    sm=ext_slot_map(edges)
    Ev=[e for e in E if e[2]>=score]
    out=[]
    internal=[(u,v) for u,v in edges if u!=0 and v!=0]
    for e1 in Ev:
      for e2 in Ev:
       for e3 in Ev:
        es={1:e1,2:e2,3:e3}
        ok=True
        for u,v in internal:
            if not bridge_ok(es[u],sm[u][v],es[v],sm[v][u]): ok=False; break
        if ok: out.append((e1,e2,e3))
    return out,sm

def make_record(core, es, edges, core_port_map):
    sm=ext_slot_map(edges)
    used_core=set(core_port_map.values())
    core_keep=[p for p in range(5) if p not in used_core]
    boundary=[core[1][p] for p in core_keep]
    for eidx,e in zip((1,2,3),es):
        used=set(sm[eidx].values())
        boundary.extend(e[1][s] for s in range(3) if s not in used)
    return (core[0]|es[0][0]|es[1][0]|es[2][0],tuple(boundary),min(core[2],es[0][2],es[1][2],es[2][2]),tuple(core[3])+(es[0][3],es[1][3],es[2][3]),int(core[4] and es[0][4] and es[1][4] and es[2][4]))

def feasible_core(core, es, edges, core_port_map, raw=False, tr=None):
    sm=ext_slot_map(edges); em={1:es[0],2:es[1],3:es[2]}
    for u,v in edges:
        if u==0:
            p=core_port_map[v]
            if raw:
                if not pmok(rawslot(tr,p),em[v][1][sm[v][0]]): return False
            else:
                if not bridge_ok(core,p,em[v],sm[v][0]): return False
    return True
